for name, pairs in DATA.items():
    out_dir = os.path.join(REPO, "data", "experts", name)
    out_path = os.path.join(out_dir, f"{name}_new.txt")
    with open(out_path, "w") as f:
        for q, a in pairs:
            f.write(f"User: {q}\nJoe: {a}\n\n")
    print(f"{name}: {len(pairs)} new Q&A pairs -> {out_path}")

print("\nDone. Review *_new.txt files, then merge with: cat file >> train_file")
